def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    remaining = 100 - n
    if remaining <= 2:
        return 'D'

    opp_d = 0
    my_d = 0
    for a, b in history:
        if b == 'D':
            opp_d += 1
        if a == 'D':
            my_d += 1

    # If opponent never defected
    if opp_d == 0:
        if my_d > 0:
            return 'D'  # exploit
        if n >= 20 and n % 10 == 0:
            return 'D'  # probe
        return 'C'

    # If opponent always defected
    if opp_d == n:
        return 'D'

    recent = history[-8:] if n >= 8 else history
    recent_opp_d = 0
    for a, b in recent:
        if b == 'D':
            recent_opp_d += 1

    last_my, last_opp = history[-1]

    if opp_d * 5 > n * 3:
        if last_opp == 'C':
            return 'D'
        return 'D' if n % 7 != 0 else 'C'

    if opp_d * 5 < n:
        if last_opp == 'D':
            if last_my == 'D':
                return 'C'
            if recent_opp_d >= 2:
                return 'D'
            return 'C'
        return 'C'

    # Mixed case
    if last_opp == 'D':
        if last_my == 'D':
            return 'C'
        if n >= 2 and history[-2][0] == 'D':
            return 'C'
        return 'D'
    else:
        if last_my == 'D':
            return 'C'
        return 'C'
